/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class AuthTokenInfo : JsObject
{
    public AuthTokenInfo(IntPtr handle) : base(handle) { }
    private static ReadOnlySpan<byte> _authType => "authType"u8;
    private static ReadOnlySpan<byte> _token => "token"u8;
    private static ReadOnlySpan<byte> _account => "account"u8;
    /// <summary>
    /// authType
    /// </summary>
    public string AuthType => NativeValue.ToString(GetPropertyRaw(_authType)) ?? string.Empty;

    /// <summary>
    /// token
    /// </summary>
    public string Token => NativeValue.ToString(GetPropertyRaw(_token)) ?? string.Empty;

    /// <summary>
    /// account
    /// </summary>
    public AppAccountInfo? Account => GetPropertyRaw(_account) == IntPtr.Zero ? null : new AppAccountInfo(GetPropertyRaw(_account));

}

/// <summary>
/// AuthenticatorInfo 实例包装（@ohos 命名空间内嵌套接口）。
/// 由 JsObject 持有 napi 强引用；Dispose 仅释放引用，JS 对象由 ArkTS GC 管理。
/// </summary>
public sealed partial class AuthenticatorInfo : JsObject
{
    public AuthenticatorInfo(IntPtr handle) : base(handle) { }
    private static ReadOnlySpan<byte> _owner => "owner"u8;
    private static ReadOnlySpan<byte> _iconId => "iconId"u8;
    private static ReadOnlySpan<byte> _labelId => "labelId"u8;
    /// <summary>
    /// owner
    /// </summary>
    public string Owner => NativeValue.ToString(GetPropertyRaw(_owner)) ?? string.Empty;

    /// <summary>
    /// iconId
    /// </summary>
    public double IconId => NativeValue.ToDouble(GetPropertyRaw(_iconId));

    /// <summary>
    /// labelId
    /// </summary>
    public double LabelId => NativeValue.ToDouble(GetPropertyRaw(_labelId));

}
